// Weather, publishing and backups: the jobs the hourly maintenance run chains.
import { execFile } from "node:child_process";
import { copyFileSync, cpSync, mkdirSync, readdirSync, rmSync, statSync, writeFileSync } from "node:fs";
import path from "node:path";
import { backup as sqliteBackup } from "node:sqlite";
import { promisify } from "node:util";
import { publishable, type Run } from "./analysis.ts";
import {
  BACKUP_DIR, BACKUP_GPG_RECIPIENT, BACKUP_KEEP, DATA_DIR, PUBLISH_DIR, PUBLISH_SUBDIR, ROOT,
  WEATHER_LATITUDE, WEATHER_LONGITUDE,
} from "./config.ts";
import { all, db, get, nowIso, run } from "./db.ts";
import { addDays, CONFIRMATORY_FIELDS, studyDayAndSlot } from "./study.ts";

const execFileAsync = promisify(execFile);

// ---------------------------------------------------------------- weather

const FORECAST_URL = "https://api.open-meteo.com/v1/forecast";
const ARCHIVE_URL = "https://archive-api.open-meteo.com/v1/archive";
const AIR_URL = "https://air-quality-api.open-meteo.com/v1/air-quality";
const DAILY_VARS = "temperature_2m_mean,precipitation_sum,sunshine_duration,daylight_duration";
const ARCHIVE_LAG_DAYS = 5; // the archive trails a few days; the forecast API covers the recent past

type WeatherRow = Partial<Record<"temp_mean_c" | "precipitation_mm" | "sunshine_hours" | "daylight_hours" | "pm25", number>>;

async function getJson(url: string, params: Record<string, string>): Promise<Record<string, Record<string, (number | string | null)[]>>> {
  const response = await fetch(`${url}?${new URLSearchParams(params)}`, { signal: AbortSignal.timeout(30_000) });
  if (!response.ok) throw new Error(`${url} answered ${response.status}`);
  return (await response.json()) as Record<string, Record<string, (number | string | null)[]>>;
}

/** Daily weather and PM2.5 from Open-Meteo. Only the rounded location leaves the machine. */
export async function fetchWeather(start: string, end: string, timeZone: string): Promise<Map<string, WeatherRow>> {
  const location = { latitude: Number(WEATHER_LATITUDE).toFixed(2), longitude: Number(WEATHER_LONGITUDE).toFixed(2), timezone: timeZone };
  const rows = new Map<string, WeatherRow>();
  const split = addDays(new Date().toISOString().slice(0, 10), -ARCHIVE_LAG_DAYS);
  const daily = async (url: string, from: string, to: string) => {
    if (from > to) return;
    const d = (await getJson(url, { ...location, daily: DAILY_VARS, start_date: from, end_date: to })).daily;
    d.time.forEach((day, i) => {
      const hours = (seconds: number | string | null) => (seconds === null ? undefined : Math.round((Number(seconds) / 3600) * 100) / 100);
      rows.set(String(day), {
        temp_mean_c: d.temperature_2m_mean[i] === null ? undefined : Number(d.temperature_2m_mean[i]),
        precipitation_mm: d.precipitation_sum[i] === null ? undefined : Number(d.precipitation_sum[i]),
        sunshine_hours: hours(d.sunshine_duration[i]),
        daylight_hours: hours(d.daylight_duration[i]),
      });
    });
  };
  await daily(ARCHIVE_URL, start, end < split ? end : addDays(split, -1));
  await daily(FORECAST_URL, start > split ? start : split, end);
  const air = (await getJson(AIR_URL, { ...location, hourly: "pm2_5", start_date: start, end_date: end })).hourly;
  const byDay = new Map<string, number[]>();
  air.time.forEach((stamp, i) => {
    const value = air.pm2_5[i];
    if (value !== null) byDay.set(String(stamp).slice(0, 10), [...(byDay.get(String(stamp).slice(0, 10)) ?? []), Number(value)]);
  });
  for (const [day, values] of byDay) {
    rows.set(day, { ...rows.get(day), pm25: Math.round((values.reduce((a, b) => a + b, 0) / values.length) * 10) / 10 });
  }
  return rows;
}

/**
 * Save the values of automatic sources into a day's log. Only real changes are
 * saved, so re-fetching does not change the data fingerprint and trigger a refit.
 * Keys are field names from this code, never from a request.
 */
export function mergeDaily(userId: number, day: string, values: Record<string, number | undefined>): boolean {
  const current = get<Record<string, number | null>>("SELECT * FROM daily_logs WHERE user_id = ? AND date = ?", userId, day) ?? {};
  const updates = Object.entries(values).filter(([key, value]) => value !== undefined && current[key] !== value);
  if (!updates.length) return false;
  run("INSERT INTO daily_logs (user_id, date) VALUES (?, ?) ON CONFLICT (user_id, date) DO NOTHING", userId, day);
  run(
    `UPDATE daily_logs SET ${updates.map(([key]) => `${key} = ?`).join(", ")}, updated_at = ? WHERE user_id = ? AND date = ?`,
    ...updates.map(([, value]) => value as number), nowIso(), userId, day,
  );
  return true;
}

/** Fill weather for complete days (up to yesterday). */
export async function syncWeather(days = 7): Promise<string> {
  if (!WEATHER_LATITUDE || !WEATHER_LONGITUDE) return "Weather is off (set WEATHER_LATITUDE and WEATHER_LONGITUDE).";
  let changed = 0;
  for (const user of all<{ id: number; time_zone: string }>("SELECT DISTINCT u.id, u.time_zone FROM users u JOIN ratings r ON r.user_id = u.id")) {
    // Yesterday in the participant's time zone: the last complete local day.
    const end = addDays(studyDayAndSlot(new Date(), user.time_zone, 0).studyDate, -1);
    const rows = await fetchWeather(addDays(end, -(days - 1)), end, user.time_zone);
    for (const [day, values] of rows) if (mergeDaily(user.id, day, values)) changed++;
  }
  return `Weather: ${changed} day(s) updated.`;
}

// ---------------------------------------------------------------- publishing

const INTERVAL_KEYS = ["est", "lo", "hi"];
const DIAGNOSTIC_KEYS = ["max_rhat", "min_ess_bulk", "divergences", "converged"];
// The site folder (results page, protocol, review record) plus two files it shares with the app.
const SHARED_FILES = [path.join(ROOT, "static", "css", "app.css"), path.join(ROOT, "static", "js", "charts.js")];

const pick = (source: Record<string, any>, keys: string[]) => Object.fromEntries(keys.map((k) => [k, source?.[k]]));
const text = (value: unknown) => String(value ?? "");
const number = (value: unknown) => (typeof value === "number" ? value : null);
const interval = (value: Record<string, any>) => Object.fromEntries(INTERVAL_KEYS.map((k) => [k, number(value?.[k])]));

/**
 * The only data that ever leaves the machine for the public page: effect
 * estimates, intervals, convergence checks and counts. Never reports, notes,
 * tags, daily values, daily series, forecasts or predictor means. Every field is
 * listed here by name, nested ones too, so nothing else can pass through. The
 * factors of the confirmatory hypotheses get no evidence label before the 6- and
 * 12-month analyses.
 */
export function publicResults(run: Run) {
  const r = run.results;
  const updated = new Date(run.finished_at ?? nowIso());
  updated.setUTCMinutes(0, 0, 0);
  const levels = (rows: Record<string, any>[]) => rows.map((t) => ({ level: text(t.level), p_happy: interval(t.p_happy) }));
  return {
    updated: updated.toISOString(),
    model_version: text(r.model.version),
    sample: { ratings: run.n_ratings, days: run.n_days },
    predictors: (r.predictors as Record<string, any>[]).map((p) => ({
      label: text(p.label), unit_label: text(p.unit_label), lag: number(p.lag),
      odds_ratio: interval(p.odds_ratio), d_happy_pp: interval(p.d_happy_pp), d_sad_pp: interval(p.d_sad_pp),
      p_positive: number(p.p_positive), direction: text(p.direction),
      evidence: CONFIRMATORY_FIELDS.has(p.field) ? "confirmatory" : text(p.evidence),
    })),
    time_of_day: levels(r.time_of_day),
    weekday: levels(r.weekday),
    dynamics: {
      phi: { ...interval(r.dynamics.phi), p_positive: number(r.dynamics.phi?.p_positive) },
      sigma_day: interval(r.dynamics.sigma_day),
    },
    diagnostics: pick(r.diagnostics, DIAGNOSTIC_KEYS),
  };
}

/** The whole public site; before the first fit there is no results.json yet. */
export function writeSite(runToPublish: Run | null, target: string): void {
  mkdirSync(target, { recursive: true });
  cpSync(path.join(ROOT, "site"), target, { recursive: true });
  for (const file of SHARED_FILES) copyFileSync(file, path.join(target, path.basename(file)));
  if (runToPublish) writeFileSync(path.join(target, "results.json"), `${JSON.stringify(publicResults(runToPublish), null, 1)}\n`, { mode: 0o644 });
}

/** Never write into the site root: that would overwrite the site's own index.html. */
export function publishTarget(dir = PUBLISH_DIR, subdir = PUBLISH_SUBDIR): { repo: string; target: string } {
  const repo = path.resolve(dir);
  const target = path.resolve(repo, subdir);
  if (target === repo || !target.startsWith(repo + path.sep)) {
    throw new Error(`PUBLISH_SUBDIR must name a folder inside ${repo}, not the repository root.`);
  }
  return { repo, target };
}

const git = async (repo: string, ...args: string[]) => (await execFileAsync("git", ["-C", repo, ...args])).stdout;

/** Write the page into the Pages clone, then commit and push only that folder. */
export async function publish(runToPublish: Run | null, message = "Update mood study results"): Promise<string> {
  if (!PUBLISH_DIR) return "Publishing is off (PUBLISH_DIR not set).";
  const { repo, target } = publishTarget();
  await git(repo, "pull", "--rebase", "--quiet");
  // Checked when the page is written: a fit that failed the checks or used another
  // study start than the one set now is never published; the pages go out alone.
  writeSite(publishable(runToPublish) ? runToPublish : null, target);
  await git(repo, "add", "--", target);
  if (!(await git(repo, "status", "--porcelain", "--", target)).trim()) return "Published results unchanged.";
  await git(repo, "commit", "--quiet", "-m", message);
  await git(repo, "push", "--quiet");
  return "Published results to GitHub Pages.";
}

// ---------------------------------------------------------------- backups

const BACKUP_EVERY_MS = 20 * 3600 * 1000;
const backups = (): string[] => {
  try {
    return readdirSync(BACKUP_DIR).filter((f) => /^study-.*\.db\.gpg$/.test(f)).sort();
  } catch {
    return [];
  }
};

export const lastBackup = (): string | null => backups().at(-1) ?? null;

export function backupDue(): boolean {
  const newest = lastBackup();
  return !newest || Date.now() - statSync(path.join(BACKUP_DIR, newest)).mtimeMs > BACKUP_EVERY_MS;
}

/** An encrypted snapshot, taken with SQLite's online backup while the server keeps running. */
export async function backupNow(): Promise<string> {
  if (!BACKUP_GPG_RECIPIENT) {
    throw new Error('Set BACKUP_GPG_RECIPIENT in .env to your backup key\'s fingerprint (create one with: gpg --quick-generate-key "AStudyOnMyself backup").');
  }
  mkdirSync(BACKUP_DIR, { recursive: true });
  const stamp = new Date().toISOString().replace(/[-:]/g, "").replace(/\..+/, "");
  const snapshot = path.join(DATA_DIR, "tmp", `backup-${stamp}.db`);
  const output = path.join(BACKUP_DIR, `study-${stamp}.db.gpg`);
  mkdirSync(path.dirname(snapshot), { recursive: true });
  try {
    await sqliteBackup(db, snapshot);
    await execFileAsync("gpg", ["--batch", "--yes", "--trust-model", "always", "--encrypt", "--recipient", BACKUP_GPG_RECIPIENT, "--output", output, snapshot]);
  } finally {
    rmSync(snapshot, { force: true });
  }
  for (const old of backups().slice(0, -BACKUP_KEEP)) rmSync(path.join(BACKUP_DIR, old));
  return `Encrypted backup written to ${output}`;

// Runs the R analysis and stores what it returns. R reads the database and
// writes JSON; this module is the only one that records runs.
import { execFile } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, rmSync } from "node:fs";
import path from "node:path";
import { promisify } from "node:util";
import { sha256 } from "./auth.ts";
import { DATA_DIR, DB_PATH, ROOT, RSCRIPT } from "./config.ts";
import { all, get, nowIso, run, transaction } from "./db.ts";
import { SLOTS, type Slot } from "./study.ts";

const execFileAsync = promisify(execFile);
const ANALYSIS_DIR = path.join(ROOT, "analysis");
const KEEP_FULL_RUNS = 10; // older runs keep only their effect estimates
const RUN_TIMEOUT_MS = 30 * 60 * 1000;
const STALE_MS = 2 * 3600 * 1000;

export type Status = "running" | "done" | "waiting" | "failed";

interface RunRow {
  id: number;
  user_id: number;
  status: Status;
  started_at: string;
  finished_at: string | null;
  n_ratings: number;
  n_days: number;
  data_fingerprint: string;
  results: string;
  message: string;
}

// The results JSON written by analysis/mood.R; see summarize_fit() there for its shape.
export type Results = Record<string, any>;
export type Run = Omit<RunRow, "results"> & { results: Results };

const parse = (row: RunRow | undefined): Run | null => (row ? { ...row, results: JSON.parse(row.results) as Results } : null);

export const getRun = (id: number): Run | null => parse(get<RunRow>("SELECT * FROM analysis_runs WHERE id = ?", id));
export const latestRun = (userId: number): Run | null =>
  parse(get<RunRow>("SELECT * FROM analysis_runs WHERE user_id = ? ORDER BY id DESC LIMIT 1", userId));
export const latestDone = (userId: number): Run | null =>
  parse(get<RunRow>("SELECT * FROM analysis_runs WHERE user_id = ? AND status = 'done' ORDER BY id DESC LIMIT 1", userId));
/** The newest finished run of any kind: tag comparisons exist even before the model can run. */
export const latestFinished = (userId: number): Run | null =>
  parse(get<RunRow>("SELECT * FROM analysis_runs WHERE user_id = ? AND status IN ('done', 'waiting') ORDER BY id DESC LIMIT 1", userId));
export const recentRuns = (userId: number, limit = 10) =>
  all<Omit<RunRow, "results">>(
    "SELECT id, user_id, status, started_at, finished_at, n_ratings, n_days, data_fingerprint, message FROM analysis_runs WHERE user_id = ? ORDER BY id DESC LIMIT ?",
    userId, limit,
  );

export const drawsPath = (runId: number): string => path.join(DATA_DIR, "posteriors", `run_${runId}.json`);

/** Changes whenever the data, the study start or the analysis code change, so hourly runs can skip. */
export function fingerprint(userId: number): string {
  const ratings = get("SELECT count(*) AS n, max(created_at) AS t FROM ratings WHERE user_id = ?", userId);
  const logs = get("SELECT count(*) AS n, max(updated_at) AS t FROM daily_logs WHERE user_id = ?", userId);
  const start = get("SELECT study_start FROM users WHERE id = ?", userId);
  const code = ["mood.R", "mood.stan", "refit.R"].map((f) => readFileSync(path.join(ANALYSIS_DIR, f), "utf8"));
  return sha256(JSON.stringify([ratings, logs, start, code]));
}

/**
 * Whether a fit may be published now: it passed the convergence checks and used
 * the study start set at this moment, read from the database at every call.
 */
export function publishable(run: Run | null): run is Run {
  const start = run ? get<{ study_start: string | null }>("SELECT study_start FROM users WHERE id = ?", run.user_id)?.study_start : null;
  return Boolean(run?.results.diagnostics?.converged && start && run.results.data?.study_start === start);
}

/** A run still marked running after two hours was killed midway. */
export function markInterrupted(): void {
  run(
    "UPDATE analysis_runs SET status = 'failed', message = 'Interrupted before it finished.', finished_at = ? WHERE status = 'running' AND started_at < ?",
    nowIso(), new Date(Date.now() - STALE_MS).toISOString(),
  );
}

/** Fit the model for one user. Returns the run, or null when skipped. */
export async function refitUser(userId: number, options: { ifNewData?: boolean } = {}): Promise<Run | null> {
  const dataFingerprint = fingerprint(userId);
  const runId = transaction(() => {
    if (get("SELECT 1 FROM analysis_runs WHERE user_id = ? AND status = 'running'", userId)) return null;
    const last = get<{ data_fingerprint: string }>(
      "SELECT data_fingerprint FROM analysis_runs WHERE user_id = ? AND status != 'running' ORDER BY id DESC LIMIT 1", userId,
    );
    if (options.ifNewData && last?.data_fingerprint === dataFingerprint) return null;
    return Number(run("INSERT INTO analysis_runs (user_id, status, data_fingerprint) VALUES (?, 'running', ?)", userId, dataFingerprint).lastInsertRowid);
  });
  if (runId === null) return null;

  const out = path.join(DATA_DIR, "tmp", `run_${runId}.json`);
  mkdirSync(path.dirname(out), { recursive: true });
  mkdirSync(path.dirname(drawsPath(runId)), { recursive: true });
  try {
    await execFileAsync(
      RSCRIPT,
      [
        path.join(ANALYSIS_DIR, "refit.R"), "--db", DB_PATH, "--user", String(userId), "--out", out,
        "--draws", drawsPath(runId), "--stan-dir", path.join(DATA_DIR, "stan"), "--seed", String(runId),
      ],
      { timeout: RUN_TIMEOUT_MS, maxBuffer: 16 * 1024 * 1024 },
    );
    const output = JSON.parse(readFileSync(out, "utf8")) as { status: Status; message?: string; results?: Results };
    const results = output.results ?? {};
    run(
      "UPDATE analysis_runs SET status = ?, message = ?, results = ?, n_ratings = ?, n_days = ?, finished_at = ? WHERE id = ?",
      output.status, output.message ?? "", JSON.stringify(results), results.data?.n_ratings ?? 0, results.data?.n_rated_days ?? 0, nowIso(), runId,
    );
  } catch (error) {
    const stderr = String((error as { stderr?: unknown }).stderr ?? "");
    const lines = stderr.split("\n").filter((l) => l.trim() && !l.includes("built under R version"));
    const message = (lines.slice(-3).join(" ") || String(error)).slice(0, 500);
    run("UPDATE analysis_runs SET status = 'failed', message = ?, finished_at = ? WHERE id = ?", message, nowIso(), runId);
  } finally {
    rmSync(out, { force: true });
  }
  prune(userId);
  return getRun(runId);
}

/** Drop bulky series and posterior draws from older runs. */
function prune(userId: number): void {
  const old = all<{ id: number; results: string }>(
    "SELECT id, results FROM analysis_runs WHERE user_id = ? AND status = 'done' ORDER BY id DESC LIMIT -1 OFFSET ?",
    userId, KEEP_FULL_RUNS,
  );
  for (const row of old) {
    rmSync(drawsPath(row.id), { force: true });
    const results = JSON.parse(row.results) as Results;
    if ("daily_mood" in results) {
      for (const key of ["daily_mood", "ppc", "forecast"]) delete results[key];
      run("UPDATE analysis_runs SET results = ? WHERE id = ?", JSON.stringify(results), row.id);
    }
  }
}

interface Draws {
  cutpoints: number[][];
  time_of_day: number[][];
  weekday_effect: number[][];
  beta: number[][];
  phi: number[];
  sigma_day: number[];
  fields: string[];
  means: number[];
  sds: number[];
}

/** Deterministic standard normals (mulberry32 plus Box-Muller), so answers do not jitter. */
function normals(seed: number): () => number {
  let a = seed >>> 0;
  const uniform = () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  return () => Math.sqrt(-2 * Math.log(1 - uniform())) * Math.cos(2 * Math.PI * uniform());
}

const logistic = (x: number): number => 1 / (1 + Math.exp(-x));

/**
 * P(Sad, Meh, Happy) per slot on a typical day with the given predictor values
 * (blank means your average). The latent daily mood is averaged over its
 * long-run distribution, so this describes a typical day, not tomorrow.
 */
export function whatIf(runId: number, values: Record<string, string>, weekday: number): Record<Slot, number[]> {
  const file = drawsPath(runId);
  if (!existsSync(file)) throw new Error("The saved posterior for this run is gone; refit first.");
  const d = JSON.parse(readFileSync(file, "utf8")) as Draws;
  const x = d.fields.map((field, j) => {
    const raw = values[field]?.trim();
    if (!raw) return 0;
    const n = Number(raw);
    if (!Number.isFinite(n)) throw new RangeError("Please enter numbers only.");
    return (n - d.means[j]) / d.sds[j];
  });
  const z = normals(1);
  const totals = SLOTS.map(() => [0, 0, 0]);
  for (let s = 0; s < d.phi.length; s++) {
    const stationarySd = d.sigma_day[s] / Math.sqrt(1 - d.phi[s] ** 2);
    const base = x.reduce((sum, xj, j) => sum + d.beta[s][j] * xj, 0) + d.weekday_effect[s][weekday] + stationarySd * z();
    SLOTS.forEach((_, k) => {
      const eta = base + d.time_of_day[s][k];
      const belowMeh = logistic(d.cutpoints[s][0] - eta);
      const belowHappy = logistic(d.cutpoints[s][1] - eta);
      totals[k][0] += belowMeh;
      totals[k][1] += belowHappy - belowMeh;
      totals[k][2] += 1 - belowHappy;
    });
  }
  const round = (v: number) => Math.round((v / d.phi.length) * 1000) / 1000;
  return Object.fromEntries(SLOTS.map((slot, k) => [slot, totals[k].map(round)])) as Record<Slot, number[]>;
}

/* One-tap mood reports with an offline queue.
 * Every report is stored on the device first (with its own timestamp and a
 * client_id) and then sent. If the server is asleep or unreachable it stays
 * queued and is sent later; the client_id keeps retries from duplicating it. */
(function () {
  "use strict";
  const KEY = "asom-queue";
  const widget = document.querySelector("[data-rate]");
  let csrfToken = document.querySelector('meta[name="csrf-token"]').content;
  let memory = [];

  if ("serviceWorker" in navigator) navigator.serviceWorker.register("/sw.js").catch(() => {});

  function load() {
    try { return JSON.parse(localStorage.getItem(KEY)) || []; } catch (e) { return memory; }
  }
  function store(queue) {
    try { localStorage.setItem(KEY, JSON.stringify(queue)); } catch (e) { memory = queue; }
  }
  function drop(id) { store(load().filter((q) => q.client_id !== id)); }
  function say(text) { if (widget) widget.querySelector("[data-status]").textContent = text; }
  function uuid() {
    if (crypto.randomUUID) return crypto.randomUUID();
    const b = crypto.getRandomValues(new Uint8Array(16));
    b[6] = (b[6] & 15) | 64; b[8] = (b[8] & 63) | 128;
    const h = [...b].map((x) => x.toString(16).padStart(2, "0")).join("");
    return `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20)}`;
  }

  function post(item) {
    return fetch("/api/ratings/", {
      method: "POST",
      credentials: "same-origin",
      headers: { "Content-Type": "application/json", "X-CSRFToken": csrfToken },
      body: JSON.stringify(item),
    });
  }

  async function freshToken() {
    const r = await fetch("/csrf/", { credentials: "same-origin" });
    // Signed out: /csrf/ redirects to the login page, which is not JSON.
    if (!r.ok || !(r.headers.get("content-type") || "").includes("json")) throw new Error("signed out");
    csrfToken = (await r.json()).token;
  }

  // The safety notice follows the server's answer (protocol Section 2.11).
  function safety(body) {
    const notice = document.querySelector("[data-safety]");
    if (notice && body && typeof body.safety === "boolean") notice.hidden = !body.safety;
  }
  async function checkSafety() {
    try {
      const r = await fetch("/api/safety/", { credentials: "same-origin" });
      if ((r.headers.get("content-type") || "").includes("json")) safety(await r.json());
    } catch (e) { /* offline: checked again next time */ }
  }

  async function saved(response) {
    if (!response.ok) return false;
    const body = await response.json().catch(() => null);
    safety(body);
    return Boolean(body && body.id);
  }

  let busy = false;
  async function flush() {
    if (busy) return;
    busy = true;
    let signedOut = false, rejected = 0, sent = 0;
    try {
      for (const item of load()) {
        let r;
        try { r = await post(item); } catch (e) { break; } // offline: keep everything
        if (r.status === 403) {
          try { await freshToken(); r = await post(item); } catch (e) { signedOut = true; break; }
        }
        if (await saved(r)) { drop(item.client_id); sent += 1; }
        else if (r.status === 400) { rejected += 1; drop(item.client_id); }
        else { signedOut = r.status === 401 || r.status === 403; break; }
      }
    } finally {
      busy = false;
    }
    const left = load().length;
    if (signedOut) say(`${left} report(s) kept on this device. Sign in to send them.`);
    else if (left) say(`Kept on this device (${left} waiting). They will be sent when the server is reachable.`);
    else if (rejected) say(`${rejected} report(s) were too old or invalid and were discarded.`);
    else if (sent) say(`Sent ${sent} report(s) saved on this device.`);
    return left;
  }

  function record(mood) {
    const note = widget.querySelector("#rate-note");
    const tags = [...widget.querySelectorAll('[data-tag][aria-pressed="true"]')].map((b) => b.dataset.tag);
    const queue = load();
    queue.push({
      client_id: uuid(),
      rating: mood,
      recorded_at: new Date().toISOString(),
      time_zone: Intl.DateTimeFormat().resolvedOptions().timeZone,
      note: note ? note.value.trim() : "",
      tags,
      source: "web",
    });
    store(queue);
    say("Saving…");
    flush().then((left) => {
      if (left) return;
      say("Saved. Thank you.");
      if (note) note.value = "";
      widget.querySelectorAll("[data-tag]").forEach((b) => b.setAttribute("aria-pressed", "false"));
      if ("reload" in widget.dataset) setTimeout(() => location.reload(), 700);
    });
  }

  if (widget) {
    widget.querySelectorAll("[data-mood]").forEach((button) => {
      button.addEventListener("click", () => record(Number(button.dataset.mood)));
    });
    widget.querySelectorAll("[data-tag]").forEach((button) => {
      button.addEventListener("click", () => {
        button.setAttribute("aria-pressed", button.getAttribute("aria-pressed") === "true" ? "false" : "true");
      });
    });
  }
  window.addEventListener("online", () => flush().then(checkSafety));
  document.addEventListener("visibilitychange", () => { if (!document.hidden) flush().then(checkSafety); });
  setInterval(flush, 60000);
  if (load().length) flush();
})();
