/bin/zsh -lc "rtk proxy node --input-type=module -e 'import { readFileSync } from '\\''node:fs'\\'';
import { runInNewContext } from '\\''node:vm'\\'';
import assert from '\\''node:assert/strict'\\'';
import { randomUUID } from '\\''node:crypto'\\'';
const source = readFileSync('\\''software/static/js/rate.js'\\'', '\\''utf8'\\'');
async function probe(staleArrivesLast) {
  const events = {}, clicks = {}, storage = new Map();
  const notice = { hidden: true }, status = { textContent: '\\'''\\'' };
  let releaseRefresh, interval;
  const widget = {
    dataset: {},
    querySelector: q => q === '\\''[data-status]'\\'' ? status : null,
    querySelectorAll: q => q === '\\''[data-mood]'\\'' ? [{ dataset: { mood: '\\''1'\\'' }, addEventListener: (name, cb) => { clicks[name] = cb; } }] : []
  };
  const document = {
    hidden: false,
    querySelector: q => q === '\\''[data-rate]'\\'' ? widget : q === '\\''[data-safety]'\\'' ? notice : { content: '\\''csrf'\\'' },
    addEventListener: (name, cb) => { events[name] = cb; }
  };
  const settle = async () => { for (let i = 0; i < 8; i++) await new Promise(setImmediate); };
  const fetch = async url => {
    if (url === '\\''/api/safety/'\\'') return new Promise(resolve => { releaseRefresh = () => resolve(Response.json({ safety: false })); });
    if (url === '\\''/api/ratings/'\\'') return Response.json({ id: 10, safety: true }, { status: 201 });
    throw Error(url);
  };
  runInNewContext(source, {
    document, window: { addEventListener: (name, cb) => { events[name] = cb; } }, navigator: {},
    localStorage: { getItem: key => storage.get(key), setItem: (key, value) => storage.set(key, value) },
    crypto: { randomUUID }, fetch, Date, Intl, setTimeout, setInterval: cb => { interval = cb; }
  });
  events.visibilitychange(); await settle();
  assert.equal(typeof releaseRefresh, '\\''function'\\'');
  if ("'!staleArrivesLast) { releaseRefresh(); await settle(); }
  clicks.click(); await settle();
  assert.equal(notice.hidden, false, '"'\\''threshold-crossing report must display notice'\\'');
  if (staleArrivesLast) { releaseRefresh(); await settle(); }
  const afterResponses = notice.hidden;
  await interval(); await settle();
  assert.equal(notice.hidden, afterResponses, '\\''empty queue interval does not repair state'\\'');
  return { responseOrder: staleArrivesLast ? '\\''new true, then old false'\\'' : '\\''old false, then new true'\\'', noticeHidden: notice.hidden, queued: JSON.parse(storage.get('\\''asom-queue'\\'')).length };
}
console.log(JSON.stringify([await probe(false), await probe(true)], null, 2));'"

